//! Manifest-vs-source consistency: the SAME dbt project loaded both ways must
//! produce the same `Dag`.
//!
//! `tests/fixtures/sample_manifest.json` is generated by REAL dbt
//! (`cargo xtask regen-sample-manifest` → `dbt compile` with dbt-duckdb) from
//! `tests/fixtures/sample_project/`, so these tests are an executable contract
//! against dbt's actual semantics — not our model of them. If the source
//! loader's parsing drifts from what dbt does (comment handling, config
//! precedence, the project config tree, disabled nodes, test capture), a
//! comparison here breaks.
//!
//! The comparison itself lives in `common::consistency` — shared with the
//! logistics fixture — including its documented exclusions (profile-derived
//! database/schema, seed CSV columns, hashed test names, singular tests,
//! the deprecation_date stamp format, and manifest-only `ref()`-in-hook
//! edges; the sample project exercises none of the last two).

mod common;
use common::consistency as cmp;
use common::{SAMPLE_MANIFEST as MANIFEST, SAMPLE_PROJECT as PROJECT};
use std::collections::BTreeMap;

use dbtl::{build_model_list, layout, run_rules, Dag, LintConfig, LintInput, NodeInfo, SortMode};

/// (manifest-mode Dag, source-mode Dag) of the same project.
fn dags() -> (Dag, Dag) {
    cmp::dags(MANIFEST, PROJECT, "cargo xtask regen-sample-manifest")
}

fn node_map(dag: &Dag) -> BTreeMap<String, NodeInfo> {
    cmp::node_map(dag)
}

#[test]
fn node_sets_and_infos_are_identical() {
    // Covers the config precedence chain, the project tree, disabled-node
    // dropping, and the comment semantics in one comparison.
    let (m, s) = dags();
    cmp::assert_node_infos_identical(&m, &s, cmp::NO_DROPPED_EDGES);
}

#[test]
fn full_lineage_closures_are_identical() {
    let (m, s) = dags();
    cmp::assert_closures_identical(&m, &s, cmp::NO_DROPPED_EDGES);
}

#[test]
fn details_are_identical_modulo_profile_data() {
    let (m, s) = dags();
    cmp::assert_details_identical(&m, &s);
}

#[test]
fn seed_columns_are_a_source_mode_superset() {
    // The one deliberate enrichment: dbt's manifest has no columns for an
    // undocumented seed; source mode surfaces the CSV header instead.
    let (m, s) = dags();
    let uid = "seed.sample.country_codes";
    assert!(
        m.detail(uid).unwrap().columns.is_empty(),
        "dbt records no columns for an undocumented seed"
    );
    let cols: Vec<&str> = s
        .detail(uid)
        .unwrap()
        .columns
        .iter()
        .map(|c| c.name.as_str())
        .collect();
    assert_eq!(cols, vec!["code", "country"], "CSV header columns surfaced");
}

#[test]
fn project_name_is_identical() {
    // The root project's name travels `metadata.project_name` (real dbt
    // ≥1.6) ↔ `dbt_project.yml`'s `name` (synthesized by source mode) — the
    // same `Dag` field either way, so both modes name the project identically.
    let (m, s) = dags();
    assert_eq!(m.project_name(), Some("sample"), "manifest mode");
    assert_eq!(s.project_name(), Some("sample"), "source mode");
}

#[test]
fn tests_are_identical_as_kind_column_multisets() {
    let (m, s) = dags();
    cmp::assert_tests_identical(&m, &s);
}

#[test]
fn exposures_are_identical_including_payload() {
    // Exposures ride the same NodeInfo/closure comparisons as every other node
    // (node_sets / closures tests above); this pins the exposure-ONLY surface:
    // the side-map payload (kind / owner / url) and the terminator contract.
    let (m, s) = dags();
    let exp_ids: Vec<String> = node_map(&m)
        .keys()
        .filter(|k| k.starts_with("exposure."))
        .cloned()
        .collect();
    assert_eq!(exp_ids.len(), 2, "sample project declares two exposures");
    for uid in &exp_ids {
        let mp = m.exposure(uid).expect("manifest-mode payload");
        let sp = s.exposure(uid).expect("source-mode payload");
        assert_eq!(mp, sp, "exposure payload diverges for {uid}");
        assert!(
            m.downstream(uid).is_empty() && s.downstream(uid).is_empty(),
            "{uid} must be a terminator leaf in both modes"
        );
        assert!(
            !m.upstream(uid).is_empty(),
            "{uid} depends on at least one kept node"
        );
    }
    // Spot-check the full payload once (the dashboard exposure).
    let dash = m
        .exposure("exposure.sample.orders_dashboard")
        .expect("dashboard payload");
    assert_eq!(dash.exposure_type.as_deref(), Some("dashboard"));
    assert_eq!(dash.owner_name.as_deref(), Some("Finance Team"));
    assert_eq!(dash.owner_email.as_deref(), Some("finance@example.com"));
    assert_eq!(
        dash.url.as_deref(),
        Some("https://bi.example.com/dashboards/42")
    );
    // And the minimal one: no email / url, still typed and owned.
    let nb = m
        .exposure("exposure.sample.churn_notebook")
        .expect("notebook payload");
    assert_eq!(nb.exposure_type.as_deref(), Some("notebook"));
    assert_eq!(nb.owner_name.as_deref(), Some("Analytics"));
    assert_eq!(nb.owner_email, None);
    assert_eq!(nb.url, None);
}

#[test]
fn model_list_and_lineage_render_identically() {
    // End-to-end: the left pane grouping and a full lineage CharGrid render are
    // byte-identical across modes (follows from Dag equality + determinism, but
    // this is the user-visible surface, so pin it directly).
    let (m, s) = dags();
    let ml = build_model_list(&m, SortMode::Layer);
    let sl = build_model_list(&s, SortMode::Layer);
    let groups = |l: &dbtl::ModelList| -> Vec<(String, Vec<String>)> {
        l.groups
            .iter()
            .map(|g| {
                (
                    g.layer.clone(),
                    g.models.iter().map(|n| n.name.clone()).collect(),
                )
            })
            .collect()
    };
    assert_eq!(groups(&ml), groups(&sl), "left-pane grouping diverges");

    // EVERY node's full lineage render (the project is tiny, so exhaustive is
    // cheap) — catches anything that escaped the structural comparisons but
    // would still show up on screen (tags, tests labels, box widths).
    for uid in node_map(&m).keys() {
        let m_lay = layout(&m.subgraph(uid));
        let s_lay = layout(&s.subgraph(uid));
        assert_eq!(
            m_lay.grid.to_text(),
            s_lay.grid.to_text(),
            "lineage render diverges for {uid}"
        );
        assert_eq!(
            m_lay.grid.emphasis_regions(),
            s_lay.grid.emphasis_regions(),
            "emphasis diverges for {uid}"
        );
    }
}

#[test]
fn lint_findings_are_identical_between_modes() {
    // The lint pass consumes graph semantics PLUS call-site positions
    // (`raw_code` offsets): the whole finding vec — rule, node, related,
    // message, severity, location, labels, help — must agree byte-for-byte
    // across modes. Same edges produce the same calls; same raw SQL maps
    // them to the same positions.
    let (m, s) = dags();
    let cfg = LintConfig::default();
    let mf = run_rules(LintInput::new(&m, &cfg)).findings;
    let sf = run_rules(LintInput::new(&s, &cfg)).findings;
    assert_eq!(
        mf.len(),
        sf.len(),
        "finding counts diverge between manifest and source modes"
    );
    for (m, s) in mf.iter().zip(&sf) {
        assert_eq!(m, s, "lint finding diverges between modes");
    }
}
